x]?0:1;age[y][x]=grid[y][x]?1:0;draw();}function randomize(){for(let y=0;y<rows;y++){for(let x=0;x<cols;x++){grid[y][x]=Math.random()<0.2?1:0;age[y][x]=grid[y][x]?1:0;}}draw();}function clear(){grid=Array.from({length:rows},()=>Array(cols).fill(0));age=Array.from({length:rows},()=>Array(cols).fill(0));dying=[];draw();}function placePattern(pattern){clear();const offsetX=Math.floor(cols/2);const offsetY=Math.floor(rows/2);pattern.forEach(([dx,dy])=>{const x=offsetX+dx;const y=offsetY+dy;if(x>=0&&x<cols&&y>=0&&y<rows){grid[y][x]=1;age[y][x]=1;}});draw();}const patterns={Glider:[[0,0],[1,0],[2,0],[2,1],[1,2]],Blinker:[[0,0],[1,0],[2,0]],GosperGun:[[-1,0],[-1,1],[0,0],[0,1],[0,2],[1,0],[1,2],[2,0],[2,1],[3,0],[3,1],[4,0],[4,-1],[5,-2],[5,-1],[6,-2],[6,-1],[5,2],[5,3],[6,2],[6,3],[7,1],[7,0],[8,1],[8,0],[9,0],[9,-1],[10,-1],[10,-2]],Pulsar:[[2,0],[3,0],[4,0],[8,0],[9,0],[10,0],[2,5],[3,5],[4,5],[8,5],[9,5],[10,5],[2,7],[3,7],[4,7],[8,7],[9,7],[10,7],[2,12],[3,12],[4,12],[8,12],[9,12],[10,12],[0,2],[0,3],[0,4],[0,8],[0,9],[0,10],[5,2],[5,3],[5,4],[5,8],[5,9],[510],[7,2],[7,3],[7,4],[7,8],[7,9],[7,10],[12,2],[12,3],[12,4],[12,8],[12,9],[12,10]]};const ui=document.createElement('div');ui.style.marginTop='10px';const select=document.createElement('select');['Glider','Blinker','Gosper Gun','Pulsar'].forEach(name=>{const opt=document.createElement('option');opt.value=name;opt.textContent=name;select.appendChild(opt);});select.addEventListener('change',()=>{placePattern(patterns[select.value.replace(' ','')]);});ui.appendChild(select);const speedLabel=document.createElement('label');speedLabel.textContent='Speed:';speedLabel.style.marginLeft='10px';const speedSlider=document.createElement('input');speedSlider.type='range';speedSlider.min='1';speedSlider.max='10';speedSlider.value='5';speedSlider.addEventListener('input',()=>{speed=parseInt(speedSlider.value);});ui.appendChild(speedLabel);ui.appendChild(speedSlider);const randBtn=document.createElement('button');randBtn.textCont